func MuambaResources() []MuambaResource {
	result := make([]MuambaResource, len(muambaResources))
	copy(result, muambaResources)
	for index := range result {
		result[index].Downloads = append([]MuambaDownload(nil), result[index].Downloads...)
	}
	return result
}

func MuambaResourceByName(name string) (MuambaResource, bool) {
	for _, resource := range MuambaResources() {
		if resource.Name == name {
			return resource, true
		}
	}
	return MuambaResource{}, false
}

func MuambaHash(resource, download string) (string, bool) {
	hash, ok := muambaHashes[resource+"\x00"+download]
	return hash, ok
}

func MuambaOpen(resource, download string) (fs.File, error) {
	path, ok := muambaEmbeddedPaths[resource+"\x00"+download]
	if !ok {
		return nil, fmt.Errorf("unknown Muamba download %s/%s", resource, download)
	}
	return muambaFiles.Open(path)
}
